    s.excnt = 1u;
    s.es[0] = 100u; s.ee[0] = 109u; s.cs[0] = 1u; s.ce[0] = 10u;
    s.phase[0] = -1;
    kprop_proj_scene_finish(&s);
    memset(&variants, 0, sizeof variants);
