    static const uint32_t ecdna_e[2] = {15u, 15u};
    static const int8_t   ephase[2]  = {0, 0};
    static const uint8_t  cds_bytes[30] = {
        'A','T','G', 'A','A','A', 'C','C','C', 'G','G','G', 'T','T','T',
        'A','T','G', 'A','A','A', 'C','C','C', 'G','G','G', 'T','T','T'
    };
